"use client";

import { ArrowUp } from "lucide-react";
import { useEffect, useState } from "react";
export function ScrollToTop() {
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    function handleScroll() {
      setVisible(window.scrollY > 500);
    }
    window.addEventListener("scroll", handleScroll, {
      passive: true
    });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);
  function scrollToTop() {
    window.scrollTo({
      top: 0,
      behavior: "smooth"
    });
  }
  if (!visible) return null;
  return <button type="button" onClick={scrollToTop} className="fixed bottom-6 right-6 z-50 p-3 rounded-full bg-[#733DD9] text-white shadow-lg
                 hover:bg-[#5B2FB0] transition-all duration-300 hover:scale-110
                 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#733DD9]
                 dark:focus:ring-offset-slate-950" aria-label="Scroll to top" data-sentry-component="ScrollToTop" data-sentry-source-file="ScrollToTop.tsx">
      <ArrowUp className="w-5 h-5" data-sentry-element="ArrowUp" data-sentry-source-file="ScrollToTop.tsx" />
    </button>;
}